# Write your MySQL query statement below
select students.student_id, student_name, students.subject_name, coalesce(count(examinations.student_id), 0) as attended_exams from (select student_id, student_name, subject_name from students cross join subjects ) students left join examinations on students.student_id= examinations.student_id and students.subject_name = examinations.subject_name group by students.student_id, student_name, students.subject_name order by students.student_id,  students.subject_name